        if (!ok) continue;
        const saved = []; for (let y = y0; y < y0 + fh; y++) for (let x = x0; x < x0 + fw; x++) { saved.push([x, y, z.get(x, y)]); z.set(x, y, T.ROCK); }
        let reach = true; if (base) { try { const r = reachN(z); reach = r[0] >= base[0] && r[1] >= base[1] - fw * fh - 2; if (reach) base = r; } catch (e) { } }
        if (!reach) { for (const [x, y, t] of saved) z.set(x, y, t); continue; }
